$roots=@('C:\Users\foto6\Downloads','C:\Users\foto6\Desktop','C:\Users\foto6\Videos','E:\');
$files=@();
foreach($r in $roots){
  if(Test-Path $r){
    $files += Get-ChildItem -Path $r -File -Recurse -ErrorAction SilentlyContinue |
      Where-Object { $_.Name -match '_DFINE_X_c(090|350)\.(mp4|detections\.jsonl)$' }
  }
}
$latest=$files | Sort-Object LastWriteTime -Descending | Select-Object -First 6;
$latest | Select-Object FullName,Length,CreationTime,LastWriteTime | Format-Table -AutoSize;
'---PROCESSES---';
Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match 'run_dfine_video\.py' } |
  Select-Object ProcessId,CreationDate,CommandLine | Format-List;
